parameters.jsCode:
const input = $json ?? {};
const execution = input.execution ?? input.closingExecution ?? {};
const evidence = input.evidence ?? {};
const auth = input.authorization ?? input.launchAuthorization ?? {};
const readiness = input.readiness ?? input.transactionReadiness ?? {};
const agreement = input.agreement ?? input.contract ?? {};
const parties = input.parties ?? {};
const price = Number(input.agreedPrice ?? agreement.agreedPrice ?? input.purchasePrice ?? NaN);
const mao = Number(input.effectiveMAO ?? input.mao ?? agreement.effectiveMAO ?? NaN);
const closingDate = input.closingDate ?? readiness.closingDate ?? null;
const launchKey = String(input.launchIdempotencyKey ?? execution.launchIdempotencyKey ?? input.idempotencyKey ?? '').trim();
const launchEvidence = input.launchEvidence ?? execution.launchEvidence ?? null;
const alreadyActive = Boolean(input.executionAlreadyActive ?? execution.active === true || execution.status === 'active');
const priorLaunchState = String(input.executionState ?? execution.state ?? '').toLowerCase();
const identityOk = Boolean(input.identityVerified ?? evidence.identityVerified);
const executedAgreementOk = Boolean(input.executedAgreementVerified ?? evidence.executedAgreementVerified ?? agreement.executed === true);
const signedEvidenceOk = Boolean(input.signedEvidenceVerified ?? evidence.signedEvidenceVerified ?? agreement.signed === true);
const agreementType = String(input.agreementType ?? agreement.type ?? '').trim();
const authorizationType = String(auth.type ?? auth.authorizationType ?? '').trim().toLowerCase();
const authorizationApproved = auth.approved === true || auth.authorized === true || auth.status === 'approved';
const authorized = authorizationApproved && ['closing_execution','closing','execution_launch','final_closing'].includes(authorizationType);
const priceProtected = Number.isFinite(price) && Number.isFinite(mao) ? price <= mao : false;
const dateValid = Boolean(closingDate) && !Number.isNaN(new Date(closingDate).getTime());
const launchEvidenceValid = Boolean(launchEvidence && (launchEvidence.id || launchEvidence.timestamp || launchEvidence.confirmed === true));
const blocked = Array.isArray(input.blockers) ? input.blockers.filter(Boolean) : [];
const missing = [];
if (!identityOk) missing.push('identity_verified');
if (!executedAgreementOk) missing.push('executed_agreement_verified');
if (!signedEvidenceOk) missing.push('signed_evidence_verified');
if (!agreementType) missing.push('agreement_type');
if (!authorized) missing.push('explicit_closing_execution_authorization');
if (!priceProtected) missing.push('agreed_price_at_or_below_effective_MAO');
if (!dateValid) missing.push('valid_closing_date');
if (!launchKey) missing.push('launch_idempotency_key');
if (blocked.length) missing.push('blockers_cleared');

let status = 'blocked';
if (blocked.length) status = 'blocked';
else if (alreadyActive || priorLaunchState === 'active') status = launchEvidenceValid ? 'already_active' : 'human_review_required';
else if (missing.length) status = 'blocked';
else status = 'launch_ready';

const activeMilestoneState = {
  status: status === 'launch_ready' ? 'active' : status,
  execution_state: status === 'launch_ready' ? 'launched_pending_milestone_confirmation' : status,
  launch_idempotency_key: launchKey || null,
  closing_date: closingDate,
  agreement_type: agreementType || null,
  agreed_price: Number.isFinite(price) ? price : null,
  effective_mao: Number.isFinite(mao) ? mao : null,
  milestone_state: status === 'launch_ready' ? 'initialized' : null,
  launch_evidence_required: status === 'launch_ready',
  launch_evidence_present: launchEvidenceValid
};

const route = status === 'launch_ready' ? 'WF-136' :
  status === 'already_active' ? 'WF-136' :
  status === 'human_review_required' ? 'WF-126' : 'WF-126';

return [{
  json: {
    ...input,
    workflow: 'WF-179',
    status,
    missing_requirements: missing,
    active_milestone_state: activeMilestoneState,
    routing: {
      next_workflow: route,
      reason: status,
      requires_human_review: status === 'human_review_required' || status === 'blocked'
    },
    audit: {
      event: 'closing_execution_launch_evaluated',
      launch_idempotency_key: launchKey || null,
      authorization_type: authorizationType || null,
      price_protected: priceProtected,
      launch_evidence_valid: launchEvidenceValid
    }
  }
}];

